import hashlib, json
from pathlib import Path

def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()

pins = json.load(open('benchmark/writing/input-pins.json'))['protected_inputs_sha256']
bad = [(k, v, sha(k) if Path(k).is_file() else 'MISSING') for k, v in pins.items()
       if not Path(k).is_file() or sha(k) != v]
print('input-pins entries', len(pins), 'mismatches', len(bad))
for b in bad:
    print('  ', b)

entries = []
def walk(o, where=''):
    if isinstance(o, dict):
        if 'path' in o and 'sha256' in o and isinstance(o['path'], str):
            entries.append((where, o['path'], o['sha256']))
        for k, v in o.items():
            walk(v, where + '/' + str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o):
            walk(v, where + '[%d]' % i)
walk(json.load(open('benchmark/preparation.json')))
bad = [(w, p, s, sha(p) if Path(p).is_file() else 'MISSING') for w, p, s in entries
       if not Path(p).is_file() or sha(p) != s]
print('preparation path/sha256 entries', len(entries), 'mismatches', len(bad))
for b in bad:
    print('  ', b)

for f in ['benchmark/scripts/score.py', 'benchmark/results/challenges.json', 'benchmark/writing/input-pins.json',
          'benchmark/preparation.json', 'benchmark/challenges/library-icon-tests.json',
          'benchmark/challenges/library-specialty.json', 'benchmark/challenges/check_xml_keys.py']:
    print(f, sha(f))

spec = json.load(open('benchmark/challenges/library-specialty.json'))
print('checker_sha256', spec['oracle']['independent_checker']['identity']['checker_sha256'])

import hashlib, json, os
from pathlib import Path

def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()

print('LABVIEW_ENVIRONMENT', os.environ.get('LABVIEW_ENVIRONMENT'))
for name in ('library-icon-tests', 'library-specialty'):
    fx = json.load(open('benchmark/challenges/%s.json' % name))
    def find(o, path=''):
        if isinstance(o, dict):
            for k, v in o.items():
                if k == 'inventory_sha256':
                    print(name, 'inventory_sha256 at', path, v)
                find(v, path + '/' + k)
        elif isinstance(o, list):
            for i, v in enumerate(o):
                find(v, path + '[%d]' % i)
    find(fx)
    print(name, 'top keys', list(fx)[:20])
    for p in sorted(Path('benchmark/cases/dev').glob('*inventory*')):
        print('  disk', p, sha(p))
    for p in sorted(Path('benchmark/cases/dev').glob(name + '*')):
        print('  disk', p, sha(p))
dev = json.load(open('benchmark/cases/dev/library-specialty.json'))
print('dev oracle checker_sha256', dev['oracle']['independent_checker']['identity']['checker_sha256'])
